from math import prod
from typing import Sequence

def encode(digits: Sequence[int], bases: Sequence[int]) -> int:
    if len(digits) != len(bases): raise ValueError("length mismatch")
    total, weight = 0, 1
    for digit, base in zip(digits, bases):
        if base < 2 or not 0 <= digit < base: raise ValueError("invalid digit")
        total += digit * weight
        weight *= base
    return total

def decode(value: int, bases: Sequence[int]) -> list[int]:
    if value < 0 or value >= prod(bases): raise ValueError("value out of range")
    out: list[int] = []
    for base in bases:
        out.append(value % base)
        value //= base
    return out

if __name__ == "__main__":
    bases = [3, 5, 7, 11]
    for n in [0, 1, 42, prod(bases)-1]:
        digits = decode(n, bases)
        print(n, digits, encode(digits, bases))

from __future__ import annotations
from math import factorial

def factorial_digits(n: int) -> list[int]:
    if n < 0: raise ValueError("n must be nonnegative")
    out, base = [0], 2
    while n:
        out.append(n % base)
        n //= base
        base += 1
    return out

def value(digits: list[int]) -> int:
    if any(not 0 <= d <= i for i, d in enumerate(digits)):
        raise ValueError("invalid factorial digit")
    return sum(d * factorial(i) for i, d in enumerate(digits))

if __name__ == "__main__":
    for n in [42, 463, 2026]:
        ds = factorial_digits(n)
        print(n, ds, value(ds))

from __future__ import annotations
from math import gcd, isqrt

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n): a, b = b, a + b
    return a

def divisors(n: int) -> list[int]:
    ds = {1}
    for d in range(2, isqrt(n)+1):
        if n % d == 0: ds.update((d, n//d))
